/*Table structure for table `manut_compras` */

DROP TABLE IF EXISTS `manut_compras`;

CREATE TABLE `manut_compras` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `titulo` varchar(100) DEFAULT NULL,
  `unidade` varchar(3) DEFAULT NULL,
  `quantidade` float DEFAULT '1',
  `quantidade_unitaria` float DEFAULT '1',
  `qtde_utilizada` float DEFAULT NULL,
  `criado_em` datetime DEFAULT NULL,
  `apagado_em` datetime DEFAULT NULL,
  `atualizado_em` datetime DEFAULT NULL,
  `comprador` varchar(50) DEFAULT NULL,
  `preco` double DEFAULT NULL,
  `data_compra` date DEFAULT NULL,
  `disponivel` smallint DEFAULT '0',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=15 DEFAULT CHARSET=utf8mb3;

